// mergeCustomers tests

test('mergeCustomers merges duplicate customer', () => {
  const customers = listCustomers();
  const invoices = [];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');

  assert.equal(result.ok, true);
  assert.equal(result.value.customers.length, customers.length - 1);
  assert(!result.value.customers.some((c) => c.id === 'C-001'));
});

test('mergeCustomers updates invoices', () => {
  const customers = listCustomers();
  const invoices = [
    { customerId: 'C-001', number: 'INV-001', total: 1000 },
    { customerId: 'C-002', number: 'INV-002', total: 2000 },
    { customerId: 'C-001', number: 'INV-003', total: 3000 },
  ];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 3);
  assert.equal(result.value.invoices.filter((inv) => inv.customerId === 'C-002').length, 3);
  assert.equal(result.value.invoices.filter((inv) => inv.customerId === 'C-001').length, 0);
});

test('mergeCustomers preserves other customer invoices', () => {
  const customers = listCustomers();
  const invoices = [
    { customerId: 'C-001', number: 'INV-001' },
    { customerId: 'C-003', number: 'INV-002' },
    { customerId: 'C-001', number: 'INV-003' },
  ];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');

  assert.equal(result.ok, true);
  const c003Invoices = result.value.invoices.filter((inv) => inv.customerId === 'C-003');
  assert.equal(c003Invoices.length, 1);
  assert.equal(c003Invoices[0].number, 'INV-002');
});

test('mergeCustomers rejects same customer', () => {
  const customers = listCustomers();
  const invoices = [];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-001');

  assert.deepEqual(result, { ok: false, error: 'SAME_CUSTOMER' });
});

test('mergeCustomers rejects unknown fromId', () => {
  const customers = listCustomers();
  const invoices = [];

  const result = mergeCustomers(customers, invoices, 'C-999', 'C-001');

  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('mergeCustomers rejects unknown intoId', () => {
  const customers = listCustomers();
  const invoices = [];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-999');

  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('mergeCustomers normalizes IDs', () => {
  const customers = listCustomers();
  const invoices = [];

  const result = mergeCustomers(customers, invoices, 'c-001', 'C-002');

  assert.equal(result.ok, true);
  assert(!result.value.customers.some((c) => c.id === 'C-001'));
});

test('mergeCustomers with case-insensitive same customer check', () => {
  const customers = listCustomers();
  const invoices = [];

  const result = mergeCustomers(customers, invoices, 'c-001', 'C-001');

  assert.deepEqual(result, { ok: false, error: 'SAME_CUSTOMER' });
});

test('mergeCustomers with spaces in IDs', () => {
  const customers = listCustomers();
  const invoices = [];

  const result = mergeCustomers(customers, invoices, '  C-001  ', '  C-002  ');

  assert.equal(result.ok, true);
  assert(!result.value.customers.some((c) => c.id === 'C-001'));
});

test('mergeCustomers does not mutate input customers', () => {
  const customers = listCustomers();
  const originalLength = customers.length;
  const invoices = [];

  mergeCustomers(customers, invoices, 'C-001', 'C-002');

  assert.equal(customers.length, originalLength);
});

test('mergeCustomers does not mutate input invoices', () => {
  const customers = listCustomers();
  const invoices = [
    { customerId: 'C-001', number: 'INV-001' },
    { customerId: 'C-002', number: 'INV-002' },
  ];
  const originalInvoice = { ...invoices[0] };

  mergeCustomers(customers, invoices, 'C-001', 'C-002');

  assert.deepEqual(invoices[0], originalInvoice);
  assert.equal(invoices[0].customerId, 'C-001');
});

test('mergeCustomers preserves invoice properties', () => {
  const customers = listCustomers();
  const invoices = [
    {
      customerId: 'C-001',
      number: 'INV-001',
      issueDate: '2025-02-15',
      total: 1000,
      status: 'issued',
